def q(
    question_id: str,
    label: str,
    answer_type: str,
    *,
    required: bool = True,
    pdf_ref: str,
    db_path: str | None = None,
    options: list[dict[str, str]] | None = None,
    ideal_answer: Any = None,
    risk_when: Any = None,
    risk_code: str | None = None,
    help_text: str | None = None,
    entry_fields: list[dict[str, Any]] | None = None,
) -> dict[str, Any]:
    return {
        "id": question_id,
        "label": label,
        "answer_type": answer_type,
        "required": required,
        "pdf_ref": pdf_ref,
        "db_path": db_path,
        "options": options or [],
        "ideal_answer": ideal_answer,
        "risk_when": risk_when,
        "risk_code": risk_code,
        "help_text": help_text,
        "entry_fields": entry_fields or [],
    }


