def all_i130_questions() -> list[dict[str, Any]]:
    return [question for page in I130_QUESTIONNAIRE for question in page["questions"]]


def all_i130a_questions() -> list[dict[str, Any]]:
    return [question for page in I130A_QUESTIONNAIRE for question in page["questions"]]


def required_family_questions(form_code: str) -> list[dict[str, Any]]:
    if form_code == "form_i130":
        return [question for question in all_i130_questions() if question["required"]]
    if form_code == "form_i130a":
        return [question for question in all_i130a_questions() if question["required"]]
    return []
